function grandHash(value){return typeof depthHash==='function'?depthHash(value):String(value).split('').reduce((h,c)=>Math.imul(h^c.charCodeAt(0),16777619)>>>0,2166136261)}
function grandPick(list,key){return list[grandHash(key)%list.length]}
function grandNames(seed){
 const first=['Aldric','Berengar','Cassian','Corvin','Darian','Edric','Leomar','Marius','Orren','Roderic','Tavian','Valric','Adelina','Celeste','Ilyra','Maelis','Rosamund','Sabine','Thalia','Vianne'];
 const houses=['Arquen','Bellafort','Corbray','Dorell','Eirenwald','Falcrest','Maroven','Rhenmark','Solvair','Veymont','Westerling','Zoric'];
 return {first,houses};
}
function createGrandHouses(seed){let n=grandNames(seed),houseOffset=grandHash(seed+':house-offset')%n.houses.length,headOffset=grandHash(seed+':head-offset')%n.first.length;return GRAND_HOUSE_PROFILES.map((p,i)=>({
  id:'house_'+i,name:`Haus ${n.houses[(houseOffset+i*5)%n.houses.length]}`,head:n.first[(headOffset+i*3)%n.first.length],heir:n.first[(headOffset+i*3+1)%n.first.length],
  ...p,power:38+grandHash(seed+':power:'+i)%39,wealth:32+grandHash(seed+':wealth:'+i)%52,relation:38+grandHash(seed+':relation:'+i)%34,
  claim:5+grandHash(seed+':claim:'+i)%28,scheme:grandHash(seed+':scheme:'+i)%24,office:false,bond:false,rival:'house_'+((i+2)%GRAND_HOUSE_PROFILES.length),usedTurn:0,memory:[],generation:1
 }))}
function createGrandCommanders(seed){let n=grandNames(seed);return GRAND_COMMANDER_PROFILES.map((p,i)=>({id:'commander_'+i,name:`${p.title} ${grandPick(n.first,seed+':commander:'+i)} von ${grandPick(n.houses,seed+':commander-house:'+i)}`,...p,skill:p.skill+grandHash(seed+':skill:'+i)%13,loyalty:48+grandHash(seed+':cmd-loyal:'+i)%35,experience:0,wounds:0,alive:true}))}
function createGrandProvinces(){let identities={
  caerhaven:['Valdorisch','bells'],falkenkrone:['Valdorisch','bells'],ravengar:['Ravisch','groves'],nordhaven:['Nordisch','ancestors'],eldoria:['Eldorisch','sun'],aurelia:['Aurelisch','sun'],lysara:['Lysarisch','stars'],islands:['Inselkulturen','tides']
 };let out={};for(const [id,[culture,religion]] of Object.entries(identities))out[id]={culture,religion,acceptance:id==='caerhaven'||id==='falkenkrone'?88:28,harmony:id==='caerhaven'||id==='falkenkrone'?84:45,rights:id==='caerhaven'||id==='falkenkrone'?'crown':'charter',culturePolicy:'protect',faithPolicy:'tolerate',buildings:{road:id==='falkenkrone'?1:0,market:id==='caerhaven'?2:0,school:id==='falkenkrone'?1:0,fort:0,port:id==='caerhaven'?2:0},construction:null,edictTurn:0,history:[]};return out}
function createGrandState(seed){return {
 government:{form:'regency',mandate:32,laws:{succession:'primogeniture',estates:'balanced',levy:'feudal',faith:'tolerant',trade:'open',provinces:'federal',justice:'customary'},coalition:['nobles','cities'],reformTurn:0,formTurn:0,history:[]},
 houses:createGrandHouses(seed),cases:[],caseSerial:0,commanders:createGrandCommanders(seed),campaigns:{},provinces:createGrandProvinces(),
 location:{current:'falkenkrone',since:1,entourage:'mother',lastTravelTurn:0,history:[]},traits:{scores:Object.fromEntries(Object.keys(GRAND_TRAITS).map(k=>[k,0])),earned:[],epithet:'DER JUNGE KÖNIG',history:[]},
 atmosphere:{sound:'off',volume:.28,weather:'clear',intensity:1,lastWeatherTurn:0},news:[],legacy:[]
 }}
function migrateGrandState(old,seed){let fresh=createGrandState(seed),g=old&&typeof old==='object'?old:{};g={...fresh,...g};
 g.government={...fresh.government,...(g.government||{}),laws:{...fresh.government.laws,...(g.government?.laws||{})},coalition:Array.isArray(g.government?.coalition)?g.government.coalition:fresh.government.coalition,history:Array.isArray(g.government?.history)?g.government.history:[]};
 g.houses=Array.isArray(g.houses)&&g.houses.length?g.houses.map((h,i)=>({...fresh.houses[i%fresh.houses.length],...h,memory:Array.isArray(h.memory)?h.memory:[]})):fresh.houses;
 g.cases=Array.isArray(g.cases)?g.cases:[];g.commanders=Array.isArray(g.commanders)&&g.commanders.length?g.commanders.map((c,i)=>({...fresh.commanders[i%fresh.commanders.length],...c})):fresh.commanders;
 g.campaigns=g.campaigns&&typeof g.campaigns==='object'?g.campaigns:{};g.provinces={...fresh.provinces,...(g.provinces||{})};for(const id of Object.keys(fresh.provinces)){let p=g.provinces[id]||{};g.provinces[id]={...fresh.provinces[id],...p,buildings:{...fresh.provinces[id].buildings,...(p.buildings||{})},history:Array.isArray(p.history)?p.history:[]}}
 g.location={...fresh.location,...(g.location||{}),history:Array.isArray(g.location?.history)?g.location.history:[]};g.traits={...fresh.traits,...(g.traits||{}),scores:{...fresh.traits.scores,...(g.traits?.scores||{})},earned:Array.isArray(g.traits?.earned)?g.traits.earned:[],history:Array.isArray(g.traits?.history)?g.traits.history:[]};g.atmosphere={...fresh.atmosphere,...(g.atmosphere||{})};g.news=Array.isArray(g.news)?g.news:[];g.legacy=Array.isArray(g.legacy)?g.legacy:[];return g}
function ensureGrand(){if(!state.grand?.government||!state.grand?.provinces||!Array.isArray(state.grand?.houses))state.grand=migrateGrandState(state.grand,state.nameSeed);return state.grand}
function grandNews(title,text,kind='realm'){let g=ensureGrand();g.news.unshift({turn:state.turn,title,text,kind});g.news=g.news.slice(0,48)}
function normalizeGrandState(s){let g=s.grand;if(!g)return;g.government.mandate=clamp(Math.round(g.government.mandate),0,100);for(const h of g.houses){for(const k of ['power','wealth','relation','claim','scheme'])h[k]=clamp(Math.round(h[k]),0,100)}for(const c of g.commanders){c.skill=clamp(Math.round(c.skill),1,100);c.loyalty=clamp(Math.round(c.loyalty),0,100);c.experience=Math.max(0,Math.round(c.experience||0));c.wounds=clamp(Math.round(c.wounds||0),0,100)}for(const p of Object.values(g.provinces)){p.acceptance=clamp(Math.round(p.acceptance),0,100);p.harmony=clamp(Math.round(p.harmony),0,100);for(const k of Object.keys(GRAND_BUILDINGS))p.buildings[k]=clamp(Math.round(p.buildings[k]||0),0,3)}for(const k of Object.keys(GRAND_TRAITS))g.traits.scores[k]=Math.max(0,Math.round(g.traits.scores[k]||0))}

function grandMandateLabel(v){return v>=75?'UNBESTRITTENE FÜHRUNG':v>=52?'TRAGFÄHIGE MEHRHEIT':v>=30?'ZERBRECHLICHES MANDAT':'OFFENE BLOCKADE'}
function grandGovernmentPanel(){let g=ensureGrand(),gov=g.government,current=GRAND_GOVERNMENTS[gov.form]||GRAND_GOVERNMENTS.regency,adult=state.life.age>=18&&!state.life.regency,forms=Object.entries(GRAND_GOVERNMENTS).filter(([id])=>id!=='regency').map(([id,f])=>{let active=gov.form===id,blocked=!adult||gov.mandate<24||state.reserve<3000000||gov.formTurn===state.turn;return `<button data-government-form="${id}" class="${active?'active':''}" ${active||blocked?'disabled':''}><small>${f.motto}</small><b>${f.name}</b><span>${f.desc}</span><em>${active?'GEGENWÄRTIGE ORDNUNG':!adult?'ERST NACH DER REGENTSCHAFT':gov.mandate<24?'POLITISCHES MANDAT FEHLT':'STAATSORDNUNG ÄNDERN'}</em></button>`}).join('');let laws=Object.entries(GRAND_LAWS).map(([cat,law])=>{let active=gov.laws[cat];return `<div class="law-family"><small>${law.label}</small>${Object.entries(law.options).map(([id,o])=>{let chosen=active===id,blocked=gov.reformTurn===state.turn||gov.mandate<12||state.reserve<(o.cost||700000);return `<button data-government-law="${cat}:${id}" class="${chosen?'active':''}" ${chosen||blocked?'disabled':''}><b>${o.name}</b><span>${o.text}</span></button>`}).join('')}</div>`}).join('');return panel('VERFASSUNG UND REICHSGESETZE',`${current.name} · ${grandMandateLabel(gov.mandate)}`,`<div class="government-hero"><div class="government-seal">§</div><div><small>STAATSORDNUNG</small><h2>${current.name}</h2><p>${current.desc}</p><blockquote>${current.motto}</blockquote></div><div class="mandate-dial" style="--mandate:${gov.mandate}"><b>${gov.mandate}</b><span>MANDAT</span></div></div><div class="government-forms">${forms}</div><div class="law-grid">${laws}</div>`,'span-12')}
function grandGovernmentFormAction(id){let g=ensureGrand(),gov=g.government,f=GRAND_GOVERNMENTS[id];if(!f||id==='regency'||state.life.age<18||state.life.regency||gov.form===id||gov.mandate<24||state.reserve<3000000||gov.formTurn===state.turn)return false;let old=GRAND_GOVERNMENTS[gov.form];state.reserve-=3000000;gov.mandate-=24;gov.form=id;gov.formTurn=state.turn;gov.coalition=[...f.support];for(const k of f.support)state.factions[k]+=5;for(const k of f.opposition)state.factions[k]-=5;let text=`Mit Siegel, Eiden und einer angespannten Ständeversammlung wird die ${old.name} durch die ${f.name} ersetzt. ${f.desc} Gegner verschwinden nicht; sie müssen in der neuen Ordnung leben oder sie zu Fall bringen.`;gov.history.unshift({turn:state.turn,type:'form',id,text});grandNews(`Neue Staatsordnung: ${f.name}`,text,'government');recordDecision(`Verfassung · ${f.name}`,text,{kind:'realm'});normalizeState();persist();render();toast('Die Ordnung des Reiches ändert sich',f.name);return true}
function grandGovernmentLawAction(code){let g=ensureGrand(),gov=g.government,[cat,id]=code.split(':'),law=GRAND_LAWS[cat],o=law?.options[id],cost=o?.cost||700000;if(!o||gov.laws[cat]===id||gov.reformTurn===state.turn||gov.mandate<12||state.reserve<cost)return false;let old=law.options[gov.laws[cat]];state.reserve-=cost;gov.mandate-=12;gov.reformTurn=state.turn;gov.laws[cat]=id;for(const k of o.support||[])state.factions[k]+=3;for(const k of o.oppose||[])state.factions[k]-=4;let text=`Das Gesetz „${o.name}“ ersetzt „${old?.name||'die bisherige Ordnung'}“. ${o.text} Familien, Ämter und Provinzen richten ihre langfristigen Pläne nun an diesem Recht aus.`;gov.history.unshift({turn:state.turn,type:'law',cat,id,text});grandNews(`Reichsgesetz: ${o.name}`,text,'government');recordDecision(`Reichsgesetz · ${o.name}`,text,{kind:'realm'});normalizeState();persist();render();toast(law.label,o.name);return true}
function grandGovernmentTick(){let g=ensureGrand(),gov=g.government;if(state.life.regency)gov.form='regency';else if(gov.form==='regency')gov.form='council';let form=GRAND_GOVERNMENTS[gov.form],base=2+(state.life.authority-40)/35+(state.stats.legitimacy-50)/45+(state.stats.stability-50)/55;for(const f of form.support||[])base+=(state.factions[f]-50)/90;for(const f of form.opposition||[])base-=(50-state.factions[f])/110;gov.mandate+=base;
 if(gov.form==='absolute'){state.stats.legitimacy+=.5;state.factions.cities-=.35}else if(gov.form==='council'){state.stats.stability+=.6;gov.mandate+=.4}else if(gov.form==='mercantile'){state.stats.trade+=.7;state.factions.merchants+=.4}else if(gov.form==='martial'){state.stats.army+=.55;state.militaryFund=Math.max(0,state.militaryFund-180000)}else if(gov.form==='popular'){state.factions.people+=.7;state.reserve=Math.max(0,state.reserve-140000)}else if(gov.form==='sacred'){state.stats.legitimacy+=.65;state.stats.intelligence-=.15}
 let l=gov.laws;if(l.trade==='open'){state.stats.trade+=.35;state.inflation+=.02}else if(l.trade==='crown'){state.reserve+=180000;state.factions.merchants-=.2}else state.factions.merchants+=.35;if(l.levy==='standing'){state.armies[0].morale+=.45;state.militaryFund=Math.max(0,state.militaryFund-210000)}else if(l.levy==='citizen'){state.stats.stability+=.2;state.factions.people+=.2}else state.factions.nobles+=.25;if(l.justice==='codified'){state.stats.stability+=.35;state.stats.intelligence+=.2}else if(l.justice==='royal')gov.mandate+=.2;
 if(l.succession==='primogeniture'){state.stats.legitimacy+=state.life.children?.length?.18:.04;for(const h of g.houses)h.claim-=.05}else if(l.succession==='designated'){state.life.authority+=.12;for(const h of g.houses)h.claim+=state.life.designatedHeir==null?.12:-.04}else{gov.mandate+=(state.factions.nobles+state.factions.cities-100)/180;for(const h of g.houses)h.claim+=.12}
 if(l.estates==='prerogative'){gov.mandate+=.28;state.factions.cities-=.22;state.factions.nobles-=.14}else if(l.estates==='chartered'){state.stats.stability+=.3;state.factions.cities+=.35;state.factions.people+=.2;state.life.authority-=.08}else{gov.mandate+=.12;state.stats.stability+=.12}
 if(l.faith==='orthodox'){state.stats.legitimacy+=.3;state.stats.intelligence-=.08}else if(l.faith==='secular'){state.stats.intelligence+=.28;state.factions.nobles-=.16}else{state.stats.stability+=.2;state.factions.cities+=.12}
 if(l.provinces==='centralized'){state.life.authority+=.18;state.reserve+=90000}else if(l.provinces==='federal'){gov.mandate+=.18;state.factions.nobles+=.12}else state.factions.people+=.18;
 let opponents=(form.opposition||[]).filter(f=>state.factions[f]<25);if(opponents.length&&grandHash(`${state.nameSeed}:constitution:${state.turn}`)%5===0){let names=opponents.map(f=>({cities:'Freie Städte',people:'Landgemeinden',nobles:'Kronadel',officers:'Offizierskorps',merchants:'Handelsgilden'}[f])).join(' und '),text=`${names} verweigern Teile der geltenden ${form.name}. Erlasse werden verzögert, Amtsträger wählen Seiten und das Mandat der Krone erodiert.`;gov.mandate-=7;state.stats.stability-=2;grandNews('Verfassungskonflikt',text,'government');state.events.unshift({turn:state.turn,date:dateLabel(),title:'Verfassungskonflikt',text})}}

function grandHousesPanel(){let g=ensureGrand(),cards=g.houses.map(h=>{let rival=g.houses.find(x=>x.id===h.rival),used=h.usedTurn===state.turn,temperature=h.relation>=65?'VERBÜNDET':h.relation>=40?'ABWARTEND':h.relation>=22?'OPPOSITIONELL':'FEINDSELIG';return `<article class="great-house ${h.relation<30?'hostile':''}" style="--house:${h.color}"><div class="house-crest">${h.crest}</div><div class="house-copy"><small>${h.seat} · ${temperature}</small><h3>${h.name}</h3><p><b>${h.head}</b> führt das Haus. Ziel: ${h.agenda}. Rivalität mit ${rival?.name||'keinem festen Lager'}.</p><div class="house-bars"><span>Bindung <i><b style="width:${h.relation}%"></b></i></span><span>Macht <i><b style="width:${h.power}%"></b></i></span><span>Anspruch <i><b style="width:${h.claim}%"></b></i></span></div></div><div class="house-actions"><button data-house-action="${h.id}:honor" ${used?'disabled':''}>EHREN<span>Rang und persönliche Anerkennung geben</span></button><button data-house-action="${h.id}:${h.office?'mission':'office'}" ${used?'disabled':''}>${h.office?'KRONAUFTRAG':'AMT GEBEN'}<span>Das Haus an Verantwortung und Macht beteiligen</span></button><button data-house-action="${h.id}:bond" ${used||h.bond?'disabled':''}>FAMILIENBAND<span>Eine Seitenlinie dynastisch verbinden</span></button><button data-house-action="${h.id}:curb" ${used?'disabled':''}>MACHT BEGRENZEN<span>Rechte prüfen und Gefolgsleute der Krone stärken</span></button></div></article>`}).join('');return panel('DIE GROSSEN HÄUSER',`${g.houses.filter(h=>h.relation<30).length} offene Gegner · ${g.houses.filter(h=>h.bond).length} Familienbande`,`<div class="great-house-grid">${cards}</div>`,'span-12')}
function grandHouseRelationsPanel(){let g=ensureGrand(),allies=g.houses.filter(h=>h.relation>=65||h.bond),rivals=g.houses.filter(h=>h.relation<30||h.claim>60);return panel('FAMILIE UND ADEL','Dynastische Bindungen reichen weit über den engsten Haushalt hinaus',`<div class="house-relation-summary"><div><small>AN DAS HAUS VALEDOR GEBUNDEN</small>${allies.map(h=>`<span style="--house:${h.color}">${h.crest} ${h.name}<b>${h.bond?'Blutsband':'treues Bündnis'}</b></span>`).join('')||'<p>Noch kein großes Haus betrachtet sein Schicksal als untrennbar mit Eurem verbunden.</p>'}</div><div><small>GEFÄHRLICHE ANSPRÜCHE</small>${rivals.map(h=>`<span style="--house:${h.color}">${h.crest} ${h.name}<b>${h.claim}% Anspruch</b></span>`).join('')||'<p>Kein Haus wagt derzeit einen offenen Anspruch auf die Krone.</p>'}</div></div>`)}
function grandHouseAction(code){let g=ensureGrand(),[id,act]=code.split(':'),h=g.houses.find(x=>x.id===id);if(!h||h.usedTurn===state.turn)return false;let text='';if(act==='honor'){if(state.private.purse<250000)return toast('Privatschatulle','Für Fest, Gaben und Zeremoniell fehlen 0,25 Mio. Gold.');state.private.purse-=250000;h.relation+=9;h.claim-=2;h.scheme-=5;text=`${h.name} erhält beim Hofzeremoniell sichtbar Rang und Gehör. ${h.head} wertet die Geste als persönliche Bindung, nicht als bloße Bestechung.`}else if(act==='office'){if(g.government.mandate<6)return toast('Politisches Mandat','Der Hof würde eine weitere große Ernennung derzeit blockieren.');g.government.mandate-=6;h.office=true;h.power+=9;h.relation+=6;for(const other of g.houses)if(other.id!==h.id)other.relation-=1;text=`${h.head} erhält ein Kronamt. ${h.name} gewinnt Zugriff auf Akten, Patronage und Entscheidungen — und trägt fortan Mitverantwortung für Erfolge wie Fehler.`}else if(act==='mission'){h.wealth+=4;h.relation+=3;h.scheme-=6;if(h.faction==='officers')state.stats.army+=2;else if(h.faction==='merchants')state.stats.trade+=2;else state.stats.stability+=2;text=`Die Krone beauftragt ${h.name}, ${h.agenda.toLowerCase()} mit staatlicher Verantwortung zu verbinden. Das Haus liefert Ergebnisse und stärkt zugleich sein eigenes Netzwerk.`}else if(act==='bond'){if(state.life.age<18)return toast('Noch zu jung','Dynastische Seitenlinien werden erst nach der Volljährigkeit verbindlich geknüpft.');if(state.reserve<1200000)return toast('Hofhaltung','Für Mitgift, Urkunden und Feier fehlen 1,2 Mio. Gold.');state.reserve-=1200000;h.bond=true;h.relation+=15;h.claim+=7;state.stats.legitimacy+=3;text=`Eine Seitenlinie des Hauses Valedor wird mit ${h.name} verbunden. Das Band schafft Verwandtschaft und Frieden — aber auch einen glaubwürdigeren Anspruch, sollte die Hauptlinie schwach werden.`}else if(act==='curb'){if(g.government.mandate<10)return toast('Politisches Mandat','Für diesen Eingriff fehlen Rückhalt und rechtliche Autorität.');g.government.mandate-=10;h.power-=10;h.wealth-=4;h.relation-=13;h.scheme+=9;text=`Königliche Prüfer begrenzen Ämter, Zölle und Gefolgsleute von ${h.name}. Die unmittelbare Macht sinkt, doch ${h.head} wird diese Demütigung nicht vergessen.`}else return false;h.usedTurn=state.turn;h.memory.unshift(text);h.memory=h.memory.slice(0,8);grandNews(`${h.name}: ${act==='curb'?'Machtkampf':'neue Bindung'}`,text,'houses');recordDecision(`Großes Haus · ${h.name}`,text,{kind:'realm'});normalizeState();persist();render();toast(h.name,'Der Adel ordnet sich neu.');return true}
function grandSpawnCase(house,forcedKind){let g=ensureGrand();if(g.cases.some(c=>!c.resolved&&c.houseId===house.id))return null;let t=forcedKind?GRAND_CASES.find(x=>x.kind===forcedKind):grandPick(GRAND_CASES,`${state.nameSeed}:case:${state.turn}:${house.id}`),serial=++g.caseSerial,c={id:`case_${serial}`,kind:t.kind,title:t.title,summary:t.summary,houseId:house.id,suspect:house.head,evidence:0,threat:22+Math.round(house.scheme/3),stage:'rumor',deadline:state.turn+5,resolved:false,actions:[],clues:[]};g.cases.unshift(c);grandNews(`Offene Untersuchung: ${c.title}`,`${c.summary} Hinweise führen in das Umfeld von ${house.name}, beweisen aber noch nichts.`,'conspiracy');state.events.unshift({turn:state.turn,date:dateLabel(),title:c.title,text:`${c.summary} Der Kronrat eröffnet eine Untersuchung, ohne den Verdacht öffentlich zu machen.`});return c}
function grandHouseTick(){let g=ensureGrand();for(const h of g.houses){let faction=state.factions[h.faction]||50,claimPressure=(g.government.laws.succession==='elective'?2:g.government.laws.succession==='designated'?1:0);h.scheme+=1.5+h.power/42+(50-h.relation)/24+claimPressure;h.wealth+=(faction-50)/70;h.claim+=(state.stats.legitimacy<40?1.2:-.15)+(h.bond?.25:0);if(h.office&&h.relation>55){h.relation+=.25;g.government.mandate+=.18}if(h.scheme>=100){h.scheme=22;if(h.relation>=58){let benefit=h.faction==='merchants'?'trade':h.faction==='officers'?'army':'stability';state.stats[benefit]+=2;h.power+=3;let text=`${h.name} vollendet aus eigener Initiative ein Vorhaben, um ${h.agenda.toLowerCase()}. Weil das Haus eng an die Krone gebunden ist, wird sein wachsender Einfluss zu valdorischer Stärke.`;grandNews(`${h.name} handelt für die Krone`,text,'houses')}else grandSpawnCase(h)}}let pair=g.houses[grandHash(`${state.nameSeed}:house-rival:${state.turn}`)%g.houses.length],rival=g.houses.find(h=>h.id===pair.rival);if(rival&&grandHash(`${state.nameSeed}:house-feud:${state.turn}`)%4===0){if(pair.relation+rival.relation>125){pair.relation+=2;rival.relation+=2;g.government.mandate+=1;grandNews('Ein Adelsstreit wird beigelegt',`${pair.name} und ${rival.name} einigen sich vor dem König auf Grenzen ihrer Rechte. Aus Rivalität wird vorerst berechenbare Konkurrenz.`,'houses')}else{pair.scheme+=5;rival.scheme+=4;state.stats.stability-=.5;grandNews('Fehde zwischen großen Häusern',`Gefolgsleute von ${pair.name} und ${rival.name} geraten über Rang, Land und alte Beleidigungen aneinander. Beide erwarten, dass die Krone Partei ergreift.`,'houses')}}}

function grandConspiracyPanel(){let g=ensureGrand(),open=g.cases.filter(c=>!c.resolved),closed=g.cases.filter(c=>c.resolved).slice(0,3),body=open.map(c=>{let h=g.houses.find(x=>x.id===c.houseId),canConfront=c.evidence>=2,canTrial=c.evidence>=3;return `<article class="conspiracy-case threat-${c.threat>=70?'high':c.threat>=40?'mid':'low'}"><div class="case-head"><div><small>${h?.name||'Unbekanntes Netzwerk'} · FRIST RUNDE ${c.deadline}</small><h3>${c.title}</h3></div><b>${Math.round(c.threat)}<span>GEFAHR</span></b></div><p>${c.summary}</p><div class="evidence-track">${[1,2,3,4].map(i=>`<i class="${c.evidence>=i?'found':''}">${c.evidence>=i?'✦':'?'}</i>`).join('')}<span>${c.evidence} belastbare Spur${c.evidence===1?'':'en'}</span></div>${c.clues.length?`<blockquote>${c.clues.at(-1)}</blockquote>`:''}<div class="case-actions"><button data-case-action="${c.id}:records">AKTEN & GELDWEGE PRÜFEN<span>Langsam, sachlich und schwer zu manipulieren</span></button><button data-case-action="${c.id}:witnesses">ZEUGEN GETRENNT VERNEHMEN<span>Schneller, aber Gerüchte erreichen den Hof</span></button><button data-case-action="${c.id}:protect">ZIELPERSONEN SCHÜTZEN<span>Gefahr senken, ohne den Täter zu entlarven</span></button><button data-case-action="${c.id}:confront" ${canConfront?'':'disabled'}>VERDÄCHTIGEN KONFRONTIEREN<span>Benötigt mindestens zwei belastbare Spuren</span></button><button data-case-action="${c.id}:trial" ${canTrial?'':'disabled'}>ÖFFENTLICHEN PROZESS ERÖFFNEN<span>Mindestens drei Spuren für ein tragfähiges Urteil</span></button><button data-case-action="${c.id}:pardon">GEHEIME BEGNADIGUNG ANBIETEN<span>Das Netzwerk binden, aber Schuld ungesühnt lassen</span></button></div></article>`}).join('')||'<div class="empty deep-empty">Derzeit liegt keine offene Verschwörung vor. Ruhe bedeutet jedoch nicht, dass die großen Häuser keine Pläne verfolgen.</div>';let archive=closed.length?`<div class="case-archive"><small>ABGESCHLOSSENE FÄLLE</small>${closed.map(c=>`<span><b>${c.title}</b>${c.outcome}</span>`).join('')}</div>`:'';return panel('GEHEIMNISSE UND VERSCHWÖRUNGEN',`${open.length} offene Untersuchung${open.length===1?'':'en'} · Beweise statt bloßer Verdacht`,`<div class="conspiracy-board">${body}${archive}</div>`,'span-12')}
function grandCaseAction(code){let g=ensureGrand(),[id,act]=code.split(':'),c=g.cases.find(x=>x.id===id&&!x.resolved),h=c&&g.houses.find(x=>x.id===c.houseId);if(!c||!h)return false;let roll=grandHash(`${state.nameSeed}:${c.id}:${act}:${state.turn}:${c.actions.length}`)%100,text='';if(act==='records'){if(state.reserve<450000)return toast('Untersuchungskosten','Für Schreiber, Reisen und Buchprüfung fehlen 0,45 Mio. Gold.');state.reserve-=450000;let found=roll<70;c.evidence+=found?1:0;c.threat+=found?3:6;c.stage='records';let clue=found?`In den Büchern von ${h.name} tauchen wiederkehrende Zahlungen an einen Diener des ${c.kind==='guards'?'Osttors':'Palastes'} auf.`:'Die Bücher sind auffällig sauber. Jemand könnte Spuren entfernt haben, oder der Verdacht führt in die falsche Richtung.';c.clues.push(clue);text=clue}else if(act==='witnesses'){let found=roll<58;c.evidence+=found?1:0;c.threat+=8;h.relation-=2;c.stage='witnesses';let clue=found?`Zwei getrennte Aussagen erwähnen denselben Boten aus ${h.seat}; ihre Einzelheiten stimmen überein.`:'Die Aussagen widersprechen einander. Am Hof verbreitet sich dennoch, wen die Krone verdächtigt.';c.clues.push(clue);text=clue}else if(act==='protect'){if(state.reserve<900000)return toast('Schutzmaßnahmen','Für Wachen, sichere Räume und Gegenproben fehlen 0,9 Mio. Gold.');state.reserve-=900000;c.threat-=22;state.stats.stability+=1;text='Wachen, Küchen und Archive werden neu geordnet. Das Netzwerk verliert Gelegenheit, bleibt aber zunächst unerkannt.'}else if(act==='confront'){if(c.evidence<2)return false;c.stage='confronted';c.threat-=12;h.relation-=8;h.scheme-=12;let admits=roll<45+c.evidence*10;if(admits){c.evidence+=1;let clue=`${c.suspect} räumt Kontakte und Zahlungen ein, bestreitet jedoch den eigentlichen Anschlagsplan.`;c.clues.push(clue);text=clue}else{text=`${c.suspect} weist alles zurück und mobilisiert Verwandte. Die Konfrontation zwingt das Netzwerk zur Vorsicht, politisiert aber die Untersuchung.`;h.power+=2}}else if(act==='trial'){if(c.evidence<3)return false;let success=roll<35+c.evidence*17;c.resolved=true;if(success){c.outcome=`Schuld nach ${c.evidence} Spuren bewiesen`;h.power-=14;h.claim-=10;h.relation-=18;h.scheme=5;state.stats.legitimacy+=4;state.stats.stability+=2;text=`Zeugen, Bücher und Gegenstände ergeben vor dem Kronrecht ein geschlossenes Bild. ${c.suspect} wird verurteilt; ${h.name} verliert Ämter und Anspruch, ohne dass bloßer Verdacht zum Gesetz wird.`}else{c.outcome='Prozess endet ohne tragfähiges Urteil';h.relation-=22;h.claim+=8;state.stats.legitimacy-=6;state.stats.stability-=4;text=`Die Verteidigung zerlegt entscheidende Beweise. Der Prozess endet ohne sicheres Urteil und macht aus ${h.name} ein gekränktes Sammelbecken der Opposition.`}}else if(act==='pardon'){c.resolved=true;c.outcome='Geheime Begnadigung gegen Eid';c.threat=0;h.relation+=8;h.scheme=8;h.claim+=3;g.government.mandate-=3;text=`${c.suspect} erhält im Verborgenen Vergebung gegen Geständnis, Namen und einen neuen Eid. Das unmittelbare Netzwerk zerfällt, doch die Wahrheit kann später zur Waffe gegen die Krone werden.`}else return false;c.threat=clamp(c.threat,0,100);c.actions.push({turn:state.turn,act,text});grandNews(`${c.title}: ${act}`,text,'conspiracy');recordDecision(`Untersuchung · ${c.title}`,text,{kind:'realm'});normalizeState();persist();render();toast(c.title,c.resolved?'Der Fall ist abgeschlossen.':'Die Untersuchung geht weiter.');return true}
function grandConspiracyTick(){let g=ensureGrand();for(const c of g.cases.filter(x=>!x.resolved)){c.threat+=5+Math.max(0,(state.turn-c.deadline)*3);if(c.threat>=100){let h=g.houses.find(x=>x.id===c.houseId);c.resolved=true;c.outcome='Das Netzwerk schlug vor Abschluss der Untersuchung zu';c.threat=100;state.stats.stability-=8;state.stats.legitimacy-=5;state.private.health-=c.kind==='poison'?18:5;h.claim+=12;h.power+=6;let text=`Die Untersuchung zu „${c.title}“ kommt zu spät. Das Netzwerk schlägt zu: Wachen, Archive und Hof werden erschüttert. ${h.name} bestreitet jede Verantwortung und geht politisch gestärkt aus der Ungewissheit hervor.`;grandNews('Eine Verschwörung erreicht ihr Ziel',text,'conspiracy');state.events.unshift({turn:state.turn,date:dateLabel(),title:'Eine Verschwörung erreicht ihr Ziel',text})}}
 let active=g.cases.filter(c=>!c.resolved).length;if(!active&&state.turn>4&&grandHash(`${state.nameSeed}:ambient-case:${state.turn}`)%11===0){let candidates=g.houses.filter(h=>h.relation<55).sort((a,b)=>(b.scheme+b.claim)-(a.scheme+a.claim));if(candidates[0])grandSpawnCase(candidates[0])}}

function ensureGrandCampaign(id){let g=ensureGrand(),m=COUNTRY_META[id],name=m?.key;if(!name)return null;let p=g.campaigns[name];if(!p)p=g.campaigns[name]={country:name,region:id,draft:{objective:'army',route:'river',doctrine:'balanced',retreat:'measured',commander:g.commanders.find(c=>c.alive)?.id},active:false,readiness:15,phase:'ENTWURF',startedTurn:0,issuedTurn:0,lossesAtStart:0,log:[]};p.draft={objective:'army',route:'river',doctrine:'balanced',retreat:'measured',commander:g.commanders.find(c=>c.alive)?.id,...(p.draft||{})};p.log=Array.isArray(p.log)?p.log:[];return p}
function grandWarCouncilPanel(id){let m=COUNTRY_META[id];if(!m||!state.diplo?.[m.key]?.war)return '';let g=ensureGrand(),p=ensureGrandCampaign(id),cmd=g.commanders.find(c=>c.id===p.draft.commander),used=p.issuedTurn===state.turn;let group=(key,label)=>`<div class="campaign-choice"><small>${label}</small>${Object.entries(GRAND_CAMPAIGN_OPTIONS[key]).map(([v,o])=>`<button data-campaign-plan="${id}:${key}:${v}" class="${p.draft[key]===v?'active':''}" ${used?'disabled':''}><b>${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div>`;let commanders=g.commanders.filter(c=>c.alive).map(c=>`<button data-campaign-plan="${id}:commander:${c.id}" class="${p.draft.commander===c.id?'active':''}" ${used?'disabled':''}><b>${c.name}</b><span>${c.specialty.toUpperCase()} · Erfahrung ${c.experience} · Loyalität ${c.loyalty}</span></button>`).join('');return `<section class="war-council"><div class="war-council-head"><div><div class="eyebrow">KÖNIGLICHER KRIEGSRAT</div><h3>${p.active?p.phase:'Feldzugsplan im Entwurf'}</h3><p>${p.active?`Seit Runde ${p.startedTurn} führt ${cmd?.name||'der Generalstab'} den Plan. Bereitschaft ${Math.round(p.readiness)}%.`:'Ziel, Route, Befehlshaber, Doktrin und Rückzug werden gemeinsam beschlossen.'}</p></div><div class="campaign-readiness"><b>${Math.round(p.readiness)}%</b><span>BEREITSCHAFT</span></div></div><div class="campaign-grid">${group('objective','KRIEGSZIEL')}${group('route','MARSCH- UND VERSORGUNGSROUTE')}${group('doctrine','OPERATIVE DOKTRIN')}${group('retreat','RÜCKZUGSBEFEHL')}<div class="campaign-choice"><small>OBERBEFEHL</small>${commanders}</div></div><button class="campaign-issue" data-campaign-plan="${id}:issue:plan" ${used||state.militaryFund<1500000?'disabled':''}>${p.active?'FELDZUGSPLAN ANPASSEN':'FELDZUGSPLAN BESIEGELN'}<span>1,5 Mio. aus dem Militärfonds · alle Frontbefehle folgen danach diesem Plan</span></button>${p.log.length?`<div class="campaign-log"><small>FELDZUGSCHRONIK</small>${p.log.slice(0,4).map(x=>`<p><b>Runde ${x.turn} · ${x.phase}</b>${x.text}</p>`).join('')}</div>`:''}</section>`}
function grandCampaignPlanAction(code){let g=ensureGrand(),[id,key,value]=code.split(':'),p=ensureGrandCampaign(id);if(!p||p.issuedTurn===state.turn)return false;if(key==='commander'){if(!g.commanders.some(c=>c.id===value&&c.alive))return false;p.draft.commander=value}else if(key==='issue'){if(state.militaryFund<1500000)return toast('Militärfonds','Für Karten, Stäbe und Magazine fehlen 1,5 Mio. Gold.');state.militaryFund-=1500000;p.active=true;p.startedTurn=p.startedTurn||state.turn;p.issuedTurn=state.turn;p.readiness=Math.max(25,p.readiness);p.phase='SAMMLUNG UND MAGAZINE';p.lossesAtStart=ensureWarDepth(COUNTRY_META[id].key).ownLosses||0;let cmd=g.commanders.find(c=>c.id===p.draft.commander);let text=`${cmd?.name||'Der Generalstab'} erhält ein vollständiges Mandat: ${GRAND_CAMPAIGN_OPTIONS.objective[p.draft.objective][0]}, über ${GRAND_CAMPAIGN_OPTIONS.route[p.draft.route][0].toLowerCase()}, nach der Doktrin „${GRAND_CAMPAIGN_OPTIONS.doctrine[p.draft.doctrine][0]}“. Der Rückzug ist ausdrücklich geregelt.`;p.log.unshift({turn:state.turn,phase:p.phase,text});grandNews(`Feldzugsplan gegen ${p.country}`,text,'war');recordDecision(`Kriegsrat · ${p.country}`,text,{kind:'war',target:p.country});normalizeState();persist();render();toast('Der Kriegsrat ist entschieden',p.country);return true}else if(GRAND_CAMPAIGN_OPTIONS[key]?.[value])p.draft[key]=value;else return false;persist();render(false);return true}
function grandCampaignModifier(id){let p=ensureGrandCampaign(id);if(!p?.active)return .82;let g=ensureGrand(),c=g.commanders.find(x=>x.id===p.draft.commander),mod=.88+(p.readiness/300)+(c?.skill||50)/500,terrain=warTerrain(id)[0];if(p.draft.route==='coastal'&&/Küste|Insel|Hafen/.test(terrain))mod+=.12;if(p.draft.route==='highland'&&/Gebirge|Hügel/.test(terrain))mod+=.1;if(p.draft.route==='river'&&/Kornland|Offenes/.test(terrain))mod+=.08;if(p.draft.doctrine==='shock'&&p.readiness>70)mod+=.12;if(p.draft.doctrine==='cautious')mod+=.03;if(p.draft.objective==='ports'&&/Küste|Insel|Hafen/.test(terrain))mod+=.08;if(c?.specialty==='supply'&&ensureWarDepth(p.country).supply<50)mod+=.08;return clamp(mod,.65,1.45)}
function grandWarOverviewPanel(){let g=ensureGrand(),wars=Object.entries(state.diplo||{}).filter(([,d])=>d.war),cards=wars.map(([name])=>{let id=countryRegionId(name),p=id&&ensureGrandCampaign(id),cmd=p&&g.commanders.find(c=>c.id===p.draft.commander);return `<article class="campaign-summary"><small>${name}</small><h3>${p?.active?p.phase:'OHNE VOLLSTÄNDIGEN FELDZUGSPLAN'}</h3><p>${p?.active?`${cmd?.name||'Generalstab'} · ${GRAND_CAMPAIGN_OPTIONS.objective[p.draft.objective][0]} · Bereitschaft ${Math.round(p.readiness)}%`:'Einzelne Angriffe bleiben möglich, aber Ziel, Nachschub und Rückzug arbeiten nicht zusammen.'}</p><button data-war-target="${id}">AUF DER KARTE PLANEN</button></article>`}).join('')||'<div class="empty">Kein offener Krieg. Die Kommandeure sammeln Erfahrung in Manövern und Garnisonen.</div>';let commanders=g.commanders.map(c=>`<div class="commander-card ${c.alive?'':'fallen'}"><b>${c.name}</b><span>${c.temper} · Schwerpunkt ${c.specialty}</span><small>Fähigkeit ${c.skill} · Erfahrung ${c.experience} · Verwundung ${c.wounds}%</small></div>`).join('');return panel('KRIEGSRAT UND OBERBEFEHL','Kriege werden als Feldzüge geplant, nicht als einzelne Würfe',`<div class="campaign-overview">${cards}</div><div class="commander-roster">${commanders}</div>`,'span-12')}
function grandCampaignTick(){let g=ensureGrand();for(const [name,dip] of Object.entries(state.diplo||{})){if(!dip.war)continue;let id=countryRegionId(name),p=id&&ensureGrandCampaign(id);if(!p?.active)continue;let c=ensureWarDepth(name),cmd=g.commanders.find(x=>x.id===p.draft.commander);let supplyGain=p.draft.route==='river'?4:p.draft.route==='coastal'?3:p.draft.route==='direct'?-1:1;p.readiness+=4+(cmd?.skill||50)/25+(p.draft.doctrine==='cautious'?2:0);c.supply+=supplyGain;if(p.readiness>=75&&p.phase==='SAMMLUNG UND MAGAZINE')p.phase='OPERATIVE HAUPTPHASE';if(c.momentum>35)p.phase='DRUCK AUF DAS FEINDLICHE ZENTRUM';let retreatAt={early:48,measured:30,hold:14}[p.draft.retreat],danger=Math.min(c.supply,state.armies[0].morale);if(danger<retreatAt&&!territoryPolicy(id).occupied){p.active=false;p.phase='GEORDNETER RÜCKZUG';c.momentum-=8;c.supply+=12;c.exhaustion-=8;state.armies[0].morale+=2;let text=`Der im Kriegsrat festgelegte Rückzugswert ist erreicht. ${cmd?.name||'Der Generalstab'} verkürzt die Front, rettet Verwundete und Magazine und verhindert, dass Ehrgeiz den Feldzug vernichtet.`;p.log.unshift({turn:state.turn,phase:p.phase,text});state.events.unshift({turn:state.turn,date:dateLabel(),title:`Geordneter Rückzug aus ${name}`,text});grandNews(`Rückzug aus ${name}`,text,'war')}else if(grandHash(`${state.nameSeed}:campaign:${state.turn}:${name}`)%3===0){let text=p.phase==='SAMMLUNG UND MAGAZINE'?'Pioniere markieren Wege, Magazine füllen sich und die Vorhut prüft Übergänge.':p.draft.doctrine==='attrition'?'Feindliche Magazine und Wege werden systematisch unter Druck gesetzt.':'Vorhut, Hauptmacht und Reserve bewegen sich gemäß dem gemeinsamen Operationsplan.';p.log.unshift({turn:state.turn,phase:p.phase,text})}p.readiness=clamp(p.readiness,0,100);p.log=p.log.slice(0,12);if(cmd){cmd.experience+=1;cmd.skill+=cmd.experience%8===0?1:0;cmd.loyalty+=(state.factions.officers-50)/80}}}

function grandOwnsRegion(id){return !COUNTRY_META[id]||isAnnexed(id)}
function grandProvince(id){return ensureGrand().provinces[id]}
function grandSelectedProvincePanel(){let id=state.selected;return grandOwnsRegion(id)?grandProvinceIdentityPanel(id):''}
function grandProvinceIdentityPanel(id){if(!grandOwnsRegion(id))return '';let p=grandProvince(id),r=state.regions[id],faith=GRAND_RELIGIONS[p.religion],builds=Object.entries(GRAND_BUILDINGS).map(([key,b])=>{let level=p.buildings[key]||0,busy=p.construction,price=Math.round(b.base*(1+level*.65));return `<div class="province-building"><i>${b.icon}</i><div><small>STUFE ${level} / 3</small><b>${b.name}</b><span>${b.text}</span></div><button data-grand-build="${id}:${key}" ${level>=3||busy||state.reserve<price?'disabled':''}>${level>=3?'VOLLENDET':busy?'BAUSTELLE AKTIV':fmt(price)+' ₲'}</button></div>`}).join('');let policy=(type,options,current)=>`<div class="identity-policy"><small>${type==='culture'?'KULTURELLE ORDNUNG':type==='faith'?'GLAUBENSRECHT':'LOKALE RECHTE'}</small>${Object.entries(options).map(([key,[name,text]])=>`<button data-identity-policy="${id}:${type}:${key}" class="${current===key?'active':''}" ${p.edictTurn===state.turn&&current!==key?'disabled':''}><b>${name}</b><span>${text}</span></button>`).join('')}</div>`;let cultureOpts={protect:['EIGENART SCHÜTZEN','Sprache, Feste und Namen bleiben öffentlich anerkannt.'],integrate:['GEMEINSAME INSTITUTIONEN','Schulen und Ämter verbinden beide Traditionen.'],replace:['VALDORISCHE EINHEIT','Amtssprache und Kronrecht sollen lokale Ordnung ersetzen.']},faithOpts={protect:['KULTSTÄTTEN SCHÜTZEN','Die regionale Religion erhält ausdrücklichen Schutz.'],tolerate:['FRIEDEN DER GEWISSEN','Mehrere Bekenntnisse leben unter gemeinsamem Recht.'],convert:['MISSION DER GLOCKEN','Tempel, Schulen und Ämter fördern den Reichsglauben.']},rightsOpts={charter:['LANDTAG & URKUNDEN','Lokale Eliten tragen Verantwortung und behalten alte Rechte.'],crown:['KRONVERWALTUNG','Beamte aus Falkenkrone setzen einheitliches Recht durch.'],martial:['MILITÄRORDNUNG','Garnison und Statthalter erhalten Vorrang.']};return `<section class="identity-admin"><div class="identity-head"><div><div class="eyebrow">KULTUR, GLAUBE UND SICHTBARER AUSBAU</div><h3>${r.name}</h3><p>${p.culture} · ${faith[2]} ${faith[0]}. Integration bedeutet nicht automatisch Zustimmung.</p></div><div><span>AKZEPTANZ <b>${p.acceptance}%</b></span><span>RELIGIONSFRIEDEN <b>${p.harmony}%</b></span></div></div>${p.construction?`<div class="province-construction"><b>${GRAND_BUILDINGS[p.construction.type].name}</b><span>Bauphase ${p.construction.progress} / ${p.construction.turns}</span><i><em style="width:${p.construction.progress/p.construction.turns*100}%"></em></i></div>`:''}<div class="province-build-grid">${builds}</div><div class="identity-policy-grid">${policy('culture',cultureOpts,p.culturePolicy)}${policy('faith',faithOpts,p.faithPolicy)}${policy('rights',rightsOpts,p.rights)}</div></section>`}
function grandStartDevelopment(code){let [id,type]=code.split(':'),p=grandProvince(id),b=GRAND_BUILDINGS[type];if(!p||!b||!grandOwnsRegion(id)||p.construction||(p.buildings[type]||0)>=3)return false;let level=p.buildings[type]||0,cost=Math.round(b.base*(1+level*.65));if(state.reserve<cost)return toast('Schatzkammer','Für diesen Ausbau reichen die Mittel nicht.');state.reserve-=cost;p.construction={type,progress:0,turns:b.turns+level,cost,startedTurn:state.turn};let text=`In ${state.regions[id].name} beginnen Arbeiten an „${b.name}“ der Stufe ${level+1}. Material, Arbeitskräfte und örtliche Rechte bestimmen die nächsten Bauphasen.`;p.history.unshift({turn:state.turn,type:'construction',text});grandNews(`Baubeginn in ${state.regions[id].name}`,text,'development');recordDecision(`Provinzausbau · ${state.regions[id].name}`,text,{kind:'development'});persist();render();toast('Baustelle eingerichtet',state.regions[id].name);return true}
function grandIdentityPolicyAction(code){let [id,type,key]=code.split(':'),p=grandProvince(id);if(!p||!grandOwnsRegion(id)||p.edictTurn===state.turn)return false;let allowed={culture:['protect','integrate','replace'],faith:['protect','tolerate','convert'],rights:['charter','crown','martial']}[type];if(!allowed?.includes(key))return false;p[type==='culture'?'culturePolicy':type==='faith'?'faithPolicy':'rights']=key;p.edictTurn=state.turn;let text=`Die Provinzordnung von ${state.regions[id].name} wird in der Frage „${type==='culture'?'Kultur':type==='faith'?'Glauben':'lokale Rechte'}“ neu ausgerichtet. Nicht nur Werte, sondern Schulen, Gerichte, Feste und Karrieren verändern sich über Jahre.`;p.history.unshift({turn:state.turn,type,key,text});grandNews(`Identitätsordnung in ${state.regions[id].name}`,text,'province');recordDecision(`Identität · ${state.regions[id].name}`,text,{kind:'development'});persist();render();return true}
function grandCompleteDevelopment(id,p){let b=GRAND_BUILDINGS[p.construction.type],type=p.construction.type;p.buildings[type]=(p.buildings[type]||0)+1;p.construction=null;let r=state.regions[id],level=p.buildings[type];if(type==='road'){r.infrastructure+=5;state.stats.trade+=1}else if(type==='market'){r.wealth+=5;state.factions.merchants+=1}else if(type==='school'){p.acceptance+=5;state.stats.intelligence+=1}else if(type==='fort'){r.garrison+=7;r.unrest-=1}else if(type==='port'){state.stats.navy+=2;r.wealth+=3}let text=`${b.name} der Stufe ${level} ist in ${r.name} vollendet. Das Bauwerk erscheint nun auf der Karte und verändert Verwaltung, Wirtschaft oder Krieg dauerhaft.`;p.history.unshift({turn:state.turn,type:'completed',text});state.events.unshift({turn:state.turn,date:dateLabel(),title:`${b.name} in ${r.name} vollendet`,text});grandNews(`Sichtbarer Ausbau: ${r.name}`,text,'development')}
function grandProvinceTick(){let g=ensureGrand(),law=g.government.laws.provinces,faithLaw=g.government.laws.faith;for(const [id,p] of Object.entries(g.provinces)){if(!grandOwnsRegion(id))continue;let r=state.regions[id];if(p.construction){let roadBonus=(p.buildings.road||0)*.2;p.construction.progress+=1+roadBonus;if(p.construction.progress>=p.construction.turns)grandCompleteDevelopment(id,p)}let accept=0,harmony=0;if(p.culturePolicy==='protect')accept+=1.2;else if(p.culturePolicy==='integrate')accept+=.8+(p.buildings.school||0)*.4;else{accept+=.35; r.unrest+=1.1}if(p.faithPolicy==='protect')harmony+=1;else if(p.faithPolicy==='tolerate')harmony+=.7;else{harmony+=.25;r.unrest+=.8}if(p.rights==='charter'){r.loyalty+=.6;accept+=.4}else if(p.rights==='crown'){r.infrastructure+=.15;accept-=.2}else{r.unrest-=.5;state.militaryFund=Math.max(0,state.militaryFund-120000)}if(law==='federal')accept+=.5;else if(law==='centralized'&&p.culture!=='Valdorisch')accept-=.4;if(faithLaw==='tolerant')harmony+=.4;else if(faithLaw==='orthodox'&&p.religion!=='bells')harmony-=.5;p.acceptance+=accept*(p.acceptance<80?1:.25);p.harmony+=harmony*(p.harmony<82?1:.25);r.loyalty+=(p.acceptance-50)/160+(p.harmony-50)/190;r.unrest-=(p.acceptance+p.harmony-100)/220;if(p.acceptance<25&&r.unrest>55){state.stats.stability-=1;grandNews(`Kultureller Widerstand in ${r.name}`,`Schulen, Gerichte und lokale Eliten verweigern die geltende Identitätsordnung. Ohne Kurswechsel wird aus passiver Ablehnung organisierter Widerstand.`,'province')}}}
function grandAnnexProvince(id){let g=ensureGrand(),p=g.provinces[id];if(!p)return;p.acceptance=Math.min(p.acceptance,24);p.harmony=Math.min(p.harmony,42);p.rights=g.government.laws.provinces==='centralized'?'crown':'charter';p.history.unshift({turn:state.turn,type:'annexed',text:`${state.regions[id].name} wurde einverleibt; Kultur und Glaube bleiben eigenständige politische Kräfte.`})}
function grandRegisterProject(id){let map={dockyard:['caerhaven','port'],road:['ravengar','road'],academy:['lysara','school'],fort:['caerhaven','fort'],lighthouse:['caerhaven','port'],university:['caerhaven','school'],tradehouse:['caerhaven','market'],rampart:['ravengar','fort'],aqueduct:['falkenkrone','road']},m=map[id];if(!m)return;let p=grandProvince(m[0]);if(p)p.buildings[m[1]]=Math.max(p.buildings[m[1]]||0,1)}
function grandMapFill(id,mode,r){let p=grandProvince(id);if(mode==='culture')return `hsl(${Math.round(p.acceptance*1.15)} 58% 46%)`;if(mode==='faith')return GRAND_RELIGIONS[p.religion]?.[1]||'#927a55';if(mode==='development'){let sum=Object.values(p.buildings).reduce((a,b)=>a+b,0);return `hsl(${38+sum*9} 58% ${34+Math.min(18,sum*2)}%)`}return null}
function grandMapValue(id,mode){let p=grandProvince(id);if(mode==='culture')return p.acceptance+'%';if(mode==='faith')return GRAND_RELIGIONS[p.religion]?.[2]||'✦';if(mode==='development')return Object.values(p.buildings).reduce((a,b)=>a+b,0)+' AUSBAU';return null}
function grandMapLayer(mode){let g=ensureGrand(),roads=[],cities=[];for(const [id,p] of Object.entries(g.provinces)){let pt=MAP_POINTS[id];if(!pt)continue;if(grandOwnsRegion(id)&&(p.buildings.road||0)>0&&id!=='caerhaven'){let home=MAP_POINTS.caerhaven;roads.push(`<path class="development-road level-${p.buildings.road}" d="M${home.x} ${home.y} Q${Math.round((home.x+pt.x)/2)} ${Math.round((home.y+pt.y)/2+18)} ${pt.x} ${pt.y}"/>`)}let icons=Object.entries(GRAND_BUILDINGS).filter(([k])=>(p.buildings[k]||0)>0).map(([k,b],i)=>`<text x="${pt.x-22+i*11}" y="${pt.y+58}" class="development-icon level-${p.buildings[k]}">${b.icon}</text>`).join('');let faith=mode==='faith'?`<text x="${pt.x}" y="${pt.y+39}" class="faith-icon">${GRAND_RELIGIONS[p.religion]?.[2]||'✦'}</text>`:'';let build=p.construction?`<g class="map-construction" transform="translate(${pt.x+25} ${pt.y-18})"><circle r="11"/><text y="3">⚒</text></g>`:'';let settlements=(GRAND_CITIES[id]||[]).map(([name,dx,dy,type],i)=>`<g class="settlement-marker ${i===0?'capital':''}" transform="translate(${pt.x+dx} ${pt.y+dy})"><circle r="${i===0?3.8:2.6}"/><text y="${i===0?-6:-5}">${name}</text><title>${name} · ${type}</title></g>`).join('');cities.push(`<g class="development-city ${grandOwnsRegion(id)?'owned':''}" data-region="${id}">${mode==='development'||grandOwnsRegion(id)?settlements:''}${icons}${faith}${build}</g>`)}return `<g class="development-roads">${roads.join('')}</g><g class="development-cities">${cities.join('')}</g>${grandWeatherLayer()}`}

function grandAvailableLocations(){let wars=Object.values(state.diplo||{}).some(d=>d.war);return Object.entries(GRAND_LOCATIONS).filter(([id,l])=>id!=='front'||wars)}
function grandArrive(id){let g=ensureGrand(),loc=g.location,dest=GRAND_LOCATIONS[id]||Object.entries(GRAND_LOCATIONS).find(([,l])=>l.region===id)?.[1],key=GRAND_LOCATIONS[id]?id:Object.keys(GRAND_LOCATIONS).find(k=>GRAND_LOCATIONS[k]===dest);if(!dest)return false;loc.current=key;loc.since=state.turn;loc.lastTravelTurn=state.turn;loc.history.unshift({turn:state.turn,location:key});loc.history=loc.history.slice(0,20);return true}
function grandSuccessionReset(){let g=ensureGrand(),fresh=createGrandState(state.nameSeed);g.traits=fresh.traits;g.location=fresh.location;g.government.reformTurn=Math.min(g.government.reformTurn||0,state.turn-1);g.cases=g.cases.filter(c=>c.resolved).slice(0,8);g.houses.forEach(h=>{h.usedTurn=0;h.scheme=Math.round((h.scheme||0)*.65);h.relation=clamp((h.relation||50)-6,5,95);h.generation=(h.generation||1)+1});g.legacy.push({turn:state.turn,type:'succession',title:'Eine neue Hand trägt die Krone',text:'Gesetze und Häuser überdauern den Monarchen, doch Ruf, Aufenthaltsort und persönliche Gewohnheiten beginnen neu.'});g.legacy=g.legacy.slice(-80)}
function grandLocationPanel(){let g=ensureGrand(),loc=g.location,current=GRAND_LOCATIONS[loc.current]||GRAND_LOCATIONS.falkenkrone,places=grandAvailableLocations().map(([id,l])=>`<button data-location-action="travel:${id}" class="${loc.current===id?'active':''}" ${loc.current===id||loc.lastTravelTurn===state.turn||state.private.actionPoints<1||state.private.purse<l.cost?'disabled':''}><i>${l.icon}</i><b>${l.name}</b><span>${l.text}</span><em>${l.cost?fmt(l.cost)+' ₲':'Königlicher Hauptsitz'}</em></button>`).join('');let entourages={mother:['KÖNIGINMUTTER','Rat, dynastische Erinnerung und Vorsicht'],spouse:['GEMAHLIN','Nähe, Diplomatie und gemeinsame Öffentlichkeit'],marshal:['MARSCHALL','Sicherheit, Heer und wenig Privatsphäre'],small:['KLEINER HOFSTAAT','Freiheit, geringere Kosten und größeres Risiko']};return panel('WO DER KÖNIG LEBT',`${current.icon} ${current.name} · seit Runde ${loc.since}`,`<div class="location-hero location-${loc.current}"><div><small>GEGENWÄRTIGER AUFENTHALT</small><h2>${current.name}</h2><p>${current.text}</p><b>${current.effect}</b></div><div class="location-actions"><button data-location-action="moment:private">EINEN PERSÖNLICHEN TAG VERBRINGEN</button><button data-location-action="moment:rule">VON HIER AUS REGIEREN</button><button data-location-action="moment:people">UNANGEKÜNDIGT MENSCHEN TREFFEN</button></div></div><div class="location-grid">${places}</div><div class="entourage-select"><small>REISEGESELLSCHAFT</small>${Object.entries(entourages).map(([id,x])=>`<button data-location-action="entourage:${id}" class="${loc.entourage===id?'active':''}"><b>${x[0]}</b><span>${x[1]}</span></button>`).join('')}</div>`)}
function grandLocationAction(code){let g=ensureGrand(),loc=g.location,[act,id]=code.split(':');if(act==='travel'){let dest=GRAND_LOCATIONS[id];if(!dest||loc.current===id||loc.lastTravelTurn===state.turn||state.private.actionPoints<1||state.private.purse<dest.cost)return false;state.private.purse-=dest.cost;state.private.actionPoints--;grandArrive(id);let text=`Der Hof verlagert sich nach ${dest.name}. Akten, Wachen, Familie und Bittsteller folgen nicht im gleichen Tempo; andere Menschen erhalten Zugang zum König.`;grandNews(`Der König reist nach ${dest.name}`,text,'private');recordDecision(`Aufenthalt · ${dest.name}`,text,{kind:'private'})}else if(act==='entourage'){if(!['mother','spouse','marshal','small'].includes(id))return false;if(id==='spouse'&&!state.life.spouse)return toast('Keine Gemahlin','Dieser Reisegesellschaft fehlt noch eine königliche Gemahlin.');loc.entourage=id;let text=`Künftige Reisen werden mit ${id==='mother'?'der Königinmutter':id==='spouse'?'der Gemahlin':id==='marshal'?'dem Marschall und starker Wache':'einem kleinen, persönlichen Hofstaat'} unternommen. Das verändert Gespräche, Sicherheit und Nähe.`;recordDecision('Reisegesellschaft',text,{kind:'private'})}else if(act==='moment'){if(state.private.actionPoints<1)return false;state.private.actionPoints--;let current=GRAND_LOCATIONS[loc.current];if(id==='private'){state.private.stress-=10;if(loc.entourage==='spouse')state.private.queen+=6;else if(loc.entourage==='mother')state.private.mother+=5;else state.private.health+=2}else if(id==='rule'){state.life.authority+=4;g.government.mandate+=3;state.private.stress+=3}else{state.factions.people+=4;state.private.reputation+=2;state.private.secret+=loc.entourage==='small'?3:0}let text=`In ${current.name} wird aus dem Aufenthalt eine bewusste Entscheidung: ${id==='private'?'Der Mensch hinter der Krone erhält Zeit und Nähe.':id==='rule'?'Der Ort wird für Audienzen, Erlasse und sichtbare Herrschaft genutzt.':'Der König begegnet Menschen außerhalb des vorbereiteten Hofzeremoniells.'}`;recordDecision(`Ein Tag in ${current.name}`,text,{kind:'private'})}else return false;normalizeState();persist();render();return true}
function grandLocationTick(){let g=ensureGrand(),loc=g.location,id=loc.current;if(id==='front'&&!Object.values(state.diplo||{}).some(d=>d.war)){loc.current='falkenkrone';loc.since=state.turn;id='falkenkrone';grandNews('Der Feldhof kehrt heim','Mit dem Ende des letzten Krieges ziehen Karten, Wachen und königlicher Haushalt zurück nach Falkenkrone.','private')}if(id==='falkenkrone'){g.government.mandate+=.7;state.private.stress+=.4}else if(id==='caerhaven'){state.stats.trade+=.35;state.stats.navy+=.2;state.private.stress-=.4}else if(id==='sanctuary'){state.private.stress-=1.4;state.private.health+=.35;state.factions.people+=.15}else if(id==='hunt'){state.private.health+=.45;state.private.stress-=.8;state.life.courage+=.2}else if(id==='flagship'){state.stats.navy+=.5;state.private.stress+=.2;state.private.queen-=.25}else if(id==='front'){state.armies[0].morale+=1;state.factions.officers+=.45;state.private.stress+=1.1;state.private.queen-=.5;state.private.mother-=.3}if(loc.entourage==='mother'){state.life.authority+=.15;state.private.mother+=.2}else if(loc.entourage==='spouse'){state.private.queen+=.35;state.private.reputation+=.15}else if(loc.entourage==='marshal'){state.private.secret-=.3;state.factions.officers+=.2}else{state.private.stress-=.25;state.private.secret+=.15}if(grandHash(`${state.nameSeed}:location:${state.turn}:${id}`)%9===0){let current=GRAND_LOCATIONS[id],text=id==='front'?'Ein verwundeter Hauptmann bittet den König, seine Männer nicht für Ruhm zu vergeuden.':id==='sanctuary'?'Ein alter Mönch spricht nicht über Politik, sondern darüber, was der König in stillen Stunden fürchtet.':`Ein unerwarteter Besucher erreicht ${current.name} und spricht freier, als er es im Thronsaal je wagen würde.`;grandNews(`Begegnung in ${current.name}`,text,'private');state.events.unshift({turn:state.turn,date:dateLabel(),title:`Begegnung in ${current.name}`,text})}}

function grandScoreTrait(id,amount){let t=ensureGrand().traits;t.scores[id]=(t.scores[id]||0)+amount}
function rememberGrandDecision(title,text,meta={}){if(!state?.grand)return;let words=(title+' '+text).toLowerCase(),kind=meta.kind||'';if(/gnade|milde|hilfe|versorg|abgaben senken|vergeben|begnad/.test(words))grandScoreTrait('merciful',3);if(/hinricht|zerschlag|zwang|härte|ausschöpfen|unerbitt/.test(words))grandScoreTrait('ruthless',3);if(/bau|straße|hafen|schule|festung|infrastruktur|provinzausbau/.test(words))grandScoreTrait('builder',3);if(kind==='war'||/erober|angriff|feldzug|einverleib/.test(words))grandScoreTrait('conqueror',2);if(/gesandt|frieden|vermittel|vertrag|ausgleich/.test(words))grandScoreTrait('diplomat',2.5);if(/forsch|wissen|akadem|buch|gesetzbuch|schule/.test(words))grandScoreTrait('scholar',2.5);if(/handel|markt|kredit|gilde|zoll/.test(words))grandScoreTrait('merchant',2);if(/glaube|tempel|glocken|kloster|gesalbt/.test(words))grandScoreTrait('devout',3);if(kind==='private'&&/famil|kind|gemahlin|mutter|abend|nähe/.test(words))grandScoreTrait('family',3);if(/reform|verfassung|reichsgesetz|erneuer|freiheit/.test(words))grandScoreTrait('reformer',3);if(/flotte|meer|hafen|schiff|küste/.test(words))grandScoreTrait('sea',2);if(/krone|autorität|zentral|amt|ordnung|garnison/.test(words))grandScoreTrait('iron',1.5);grandEvaluateTraits();grandSoundCue(kind)}
function grandEvaluateTraits(){let g=ensureGrand(),t=g.traits;for(const [id,def] of Object.entries(GRAND_TRAITS)){if(t.earned.includes(id)||(t.scores[id]||0)<def.threshold)continue;t.earned.push(id);t.history.unshift({turn:state.turn,id,name:def.name});let text=`Hof, Volk und ausländische Gesandte beginnen, den König als „${def.name}“ zu beschreiben. Der Name entstand nicht aus einer Auswahl, sondern aus wiederholten Entscheidungen: ${def.text}`;grandNews(`Ein Beiname entsteht: ${def.name}`,text,'trait');state.events.unshift({turn:state.turn,date:dateLabel(),title:def.name,text})}let ranked=Object.keys(GRAND_TRAITS).sort((a,b)=>(t.scores[b]||0)-(t.scores[a]||0)),top=ranked.find(id=>t.earned.includes(id));t.epithet=top?GRAND_TRAITS[top].name:(state.life.age<18?'DER JUNGE KÖNIG':'DER UNBESCHRIEBENE')}
function grandTraitsPanel(){let t=ensureGrand().traits,earned=t.earned.map(id=>{let d=GRAND_TRAITS[id];return `<article class="earned-trait"><i>${d.icon}</i><div><b>${d.name}</b><p>${d.text}</p></div></article>`}).join('')||'<div class="empty">Noch hat sich kein dauerhafter Beiname gefestigt. Wiederholtes Verhalten, nicht eine Startauswahl, formt den Herrscher.</div>';let emerging=Object.entries(GRAND_TRAITS).filter(([id])=>!t.earned.includes(id)).sort((a,b)=>(t.scores[b[0]]||0)-(t.scores[a[0]]||0)).slice(0,4).map(([id,d])=>`<div class="emerging-trait"><span>${d.icon} ${d.name}</span><i><b style="width:${Math.min(100,(t.scores[id]||0)/d.threshold*100)}%"></b></i><small>${(t.scores[id]||0)>=d.threshold*.65?'Am Hof deutlich wahrnehmbar':'Noch eine leise Tendenz'}</small></div>`).join('');return panel('WER IHR GEWORDEN SEID',t.epithet,`<div class="trait-hero"><div class="trait-crown">♛</div><div><small>DER HOF NENNT EUCH</small><h2>${ensureCastNames().king}, ${t.epithet}</h2><p>Beinamen und Eigenschaften entstehen aus Mustern über viele Jahre. Sie verändern Erwartungen und laufende Wirkungen.</p></div></div><div class="earned-traits">${earned}</div><div class="emerging-traits"><small>ENTSTEHENDE WAHRNEHMUNGEN</small>${emerging}</div>`)}
function grandTraitTick(){let t=ensureGrand().traits;for(const id of t.earned){if(id==='merciful')state.factions.people+=.25;else if(id==='ruthless')state.stats.stability+=.2;else if(id==='builder')for(const r of Object.values(state.regions))r.infrastructure+=.03;else if(id==='conqueror')state.factions.officers+=.25;else if(id==='diplomat')for(const n of Object.keys(state.relations))state.relations[n]+=.08;else if(id==='scholar')state.stats.intelligence+=.25;else if(id==='merchant')state.stats.trade+=.25;else if(id==='devout')state.stats.legitimacy+=.2;else if(id==='family')state.private.stress-=.2;else if(id==='reformer')ensureGrand().government.mandate+=.25;else if(id==='sea')state.stats.navy+=.25;else if(id==='iron')state.life.authority+=.2}grandEvaluateTraits()}

let grandAudioEngine=null;
function grandWeatherForTurn(){let season=state.season,options=season===3?['snow','fog','clear']:season===2?['rain','storm','fog','clear']:season===1?['clear','haze','storm','rain']:['rain','clear','fog','haze'];return grandPick(options,`${state.nameSeed}:weather:${state.year}:${state.season}:${Math.floor(state.turn/2)}`)}
function grandAtmosphereTick(){let a=ensureGrand().atmosphere;if(a.lastWeatherTurn!==state.turn){a.weather=grandWeatherForTurn();a.intensity=1+grandHash(`${state.nameSeed}:weather-intensity:${state.turn}`)%3;a.lastWeatherTurn=state.turn}if(a.weather==='rain'){for(const [id,r] of Object.entries(state.regions))if(grandOwnsRegion(id))r.wealth+=.12}else if(a.weather==='storm'){state.stats.trade-=.45;state.stats.navy-=.18;for(const [name,d] of Object.entries(state.diplo||{}))if(d.war)ensureWarDepth(name).supply-=1.5}else if(a.weather==='snow'){state.militaryFund=Math.max(0,state.militaryFund-90000);for(const [name,d] of Object.entries(state.diplo||{}))if(d.war)ensureWarDepth(name).supply-=1}else if(a.weather==='clear')state.stats.trade+=.15;if(a.intensity>=3&&grandHash(`${state.nameSeed}:weather-news:${state.turn}`)%6===0){let text=a.weather==='storm'?'Sturm zwingt Handelsschiffe in die Häfen und macht Küstenfeldzüge gefährlich.':a.weather==='snow'?'Schnee verlangsamt Boten, Fuhrwerke und Heere; Wintermagazine werden entscheidend.':a.weather==='rain'?'Der Regen erschwert Märsche, verspricht dem Ackerland jedoch bessere Ernten.':'Klares Wetter beschleunigt Nachrichten, Märkte und Reisen.';grandNews(grandWeatherLabel(a.weather),text,'weather');state.events.unshift({turn:state.turn,date:dateLabel(),title:grandWeatherLabel(a.weather),text})}}
function grandWeatherLabel(w){return {clear:'Klarer Himmel',rain:'Regen über dem Reich',storm:'Sturmfront',snow:'Schneefall',fog:'Nebelbänke',haze:'Sommerdunst'}[w]||w}
function grandWeatherModifier(id){let w=ensureGrand().atmosphere.weather,terrain=typeof warTerrain==='function'?warTerrain(id)[0]:'';if(w==='storm')return /Küste|Insel|Hafen/.test(terrain)?.82:.91;if(w==='snow')return /Gebirge|Hügel/.test(terrain)?.8:.88;if(w==='rain')return .94;if(w==='fog')return .9;return 1}
function grandWeatherLayer(){let a=ensureGrand().atmosphere;if(a.weather==='clear')return '';if(a.weather==='fog'||a.weather==='haze')return `<g class="weather-map weather-${a.weather}"><path d="M0 170 Q250 110 500 175 T1024 150 M0 420 Q270 360 520 425 T1024 390"/></g>`;let count=12+a.intensity*8,marks=Array.from({length:count},(_,i)=>{let x=grandHash(`${state.turn}:wx:${i}`)%1024,y=grandHash(`${state.turn}:wy:${i}`)%768;return a.weather==='snow'?`<circle cx="${x}" cy="${y}" r="${2+i%3}"/>`:`<path d="M${x} ${y} l${a.weather==='storm'?-14:-8} ${a.weather==='storm'?28:18}"/>`}).join('');return `<g class="weather-map weather-${a.weather}">${marks}</g>`}
function grandAtmosphereStrip(){let a=ensureGrand().atmosphere,loc=GRAND_LOCATIONS[ensureGrand().location.current];return `<section class="atmosphere-strip"><div><small>WETTER ÜBER VALDORIA</small><b>${grandWeatherLabel(a.weather)}</b><span>${['Frühling','Sommer','Herbst','Winter'][state.season]} prägt Reisen, Krieg und Ernten.</span></div><div><small>DER KÖNIG WEILT</small><b>${loc?.name||'im Palast'}</b><span>${loc?.effect||'Hof'}</span></div><button data-audio-cycle><i>${a.sound==='off'?'♪':a.sound==='ambient'?'♫':'♬'}</i><b>${a.sound==='off'?'TON EINSCHALTEN':a.sound==='ambient'?'ATMOSPHÄRE':'MUSIK & ATMOSPHÄRE'}</b><span>${a.sound==='off'?'Stumm':a.sound==='ambient'?'dezente Geräuschkulisse':'volle Klangkulisse'}</span></button></section>`}
function grandStartAudio(){let A=window.AudioContext||window.webkitAudioContext;if(!A)return null;let ctx=new A(),master=ctx.createGain();master.gain.value=ensureGrand().atmosphere.volume;master.connect(ctx.destination);let filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=520;filter.connect(master);let oscillators=[55,82.41].map((freq,i)=>{let o=ctx.createOscillator(),gain=ctx.createGain();o.type=i?'triangle':'sine';o.frequency.value=freq;gain.gain.value=i?.028:.045;o.connect(gain);gain.connect(filter);o.start();return {o,gain}});grandAudioEngine={ctx,master,filter,oscillators};return grandAudioEngine}
function grandCycleAudio(){let a=ensureGrand().atmosphere;a.sound=a.sound==='off'?'ambient':a.sound==='ambient'?'full':'off';if(a.sound!=='off'&&!grandAudioEngine)grandStartAudio();if(grandAudioEngine){let now=grandAudioEngine.ctx.currentTime,target=a.sound==='off'?0:a.sound==='ambient'?a.volume*.55:a.volume;grandAudioEngine.master.gain.cancelScheduledValues(now);grandAudioEngine.master.gain.linearRampToValueAtTime(target,now+.5);grandAudioEngine.filter.frequency.linearRampToValueAtTime(a.sound==='full'?900:480,now+.6)}persist();grandApplyAtmosphere();render(false)}
function grandSoundCue(kind){if(!grandAudioEngine||ensureGrand().atmosphere.sound==='off')return;let ctx=grandAudioEngine.ctx,o=ctx.createOscillator(),gain=ctx.createGain(),freq={war:110,economy:392,private:293.66,diplomacy:349.23,development:261.63}[kind]||220;o.type=kind==='war'?'sawtooth':'sine';o.frequency.value=freq;gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.055,ctx.currentTime+.025);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.42);o.connect(gain);gain.connect(grandAudioEngine.master);o.start();o.stop(ctx.currentTime+.45)}
function grandApplyAtmosphere(){if(typeof document==='undefined'||!document.body)return;let a=ensureGrand().atmosphere;document.body.dataset.weather=a.weather;document.body.dataset.season=String(state.season);document.body.dataset.audio=a.sound;let b=document.querySelector('#audio-toggle');if(b){b.innerHTML=`<span>${a.sound==='off'?'♪':a.sound==='ambient'?'♫':'♬'}</span><small>${grandWeatherLabel(a.weather)}</small>`;b.title='Klangkulisse wechseln'}}

function grandLegacyPanel(){let g=ensureGrand(),gov=GRAND_GOVERNMENTS[g.government.form],traits=g.traits.earned.map(id=>GRAND_TRAITS[id].name).join(' · ')||'Noch kein gefestigter Beiname',houses=g.houses.filter(h=>h.bond||h.relation>=65).map(h=>h.name).join(', ')||'keine dauerhaften Adelspartner';return panel('DIE STRUKTUR EURER HERRSCHAFT',g.traits.epithet,`<div class="grand-legacy"><div><small>VERFASSUNG</small><b>${gov.name}</b><span>${Object.values(g.government.laws).map((id,i)=>Object.values(GRAND_LAWS)[i]?.options[id]?.name).filter(Boolean).join(' · ')}</span></div><div><small>DYNASTISCHE ORDNUNG</small><b>${houses}</b><span>${g.cases.filter(c=>!c.resolved).length} ungelöste Verschwörungen</span></div><div><small>CHARAKTER DER KRONE</small><b>${traits}</b><span>Aus ${state.decisions.length} aufgezeichneten Entscheidungen entstanden</span></div><div><small>SICHTBARES REICH</small><b>${Object.values(g.provinces).reduce((sum,p)=>sum+Object.values(p.buildings).reduce((a,b)=>a+b,0),0)} Ausbaustufen</b><span>Straßen, Märkte, Schulen, Festungen und Häfen</span></div></div>`,'span-12')}
function grandRealmPulse(){let g=ensureGrand(),threat=g.cases.filter(c=>!c.resolved).sort((a,b)=>b.threat-a.threat)[0],gov=GRAND_GOVERNMENTS[g.government.form],trait=g.traits.epithet;return `<section class="grand-realm-pulse"><div><small>STAATSORDNUNG</small><b>${gov.name}</b><span>${grandMandateLabel(g.government.mandate)}</span></div><div><small>DYNASTISCHE SPANNUNG</small><b>${g.houses.filter(h=>h.relation<30||h.claim>60).length} gefährliche Häuser</b><span>${threat?`${threat.title} · Gefahr ${Math.round(threat.threat)}`:'Keine offene Verschwörung'}</span></div><div><small>DER HERRSCHER</small><b>${trait}</b><span>${GRAND_LOCATIONS[g.location.current]?.name}</span></div></section>`}

function grandBindUI(){document.querySelectorAll('[data-government-form]').forEach(b=>b.onclick=()=>grandGovernmentFormAction(b.dataset.governmentForm));document.querySelectorAll('[data-government-law]').forEach(b=>b.onclick=()=>grandGovernmentLawAction(b.dataset.governmentLaw));document.querySelectorAll('[data-house-action]').forEach(b=>b.onclick=()=>grandHouseAction(b.dataset.houseAction));document.querySelectorAll('[data-case-action]').forEach(b=>b.onclick=()=>grandCaseAction(b.dataset.caseAction));document.querySelectorAll('[data-campaign-plan]').forEach(b=>b.onclick=()=>grandCampaignPlanAction(b.dataset.campaignPlan));document.querySelectorAll('[data-grand-build]').forEach(b=>b.onclick=()=>grandStartDevelopment(b.dataset.grandBuild));document.querySelectorAll('[data-identity-policy]').forEach(b=>b.onclick=()=>grandIdentityPolicyAction(b.dataset.identityPolicy));document.querySelectorAll('[data-location-action]').forEach(b=>b.onclick=()=>grandLocationAction(b.dataset.locationAction));document.querySelectorAll('[data-audio-cycle]').forEach(b=>b.onclick=grandCycleAudio);let audio=document.querySelector('#audio-toggle');if(audio)audio.onclick=grandCycleAudio}
function grandSystemsTurn(){grandGovernmentTick();grandHouseTick();grandConspiracyTick();grandCampaignTick();grandProvinceTick();grandLocationTick();grandTraitTick();grandAtmosphereTick()}
